#!/usr/bin/env bash
# Copies the shared updater (packages/waas-updater/src/Updater.php) into each plugin that updates
# itself, in that plugin's own namespace, so two of our plugins active on one site never load each
# other's copy.
#
#   scripts/sync-updater.sh          write the copies
#   scripts/sync-updater.sh --check  fail if a copy is out of date (CI)
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
source_file="$root/packages/waas-updater/src/Updater.php"
check=false
[ "${1:-}" = "--check" ] && check=true

render() { # <namespace>
  sed -e "1a\\
\\
// Generated by scripts/sync-updater.sh from packages/waas-updater/src/Updater.php: edit that file\\
// and run the script, not this copy." \
      -e "s/^namespace WaaSUpdater;\$/namespace $1;/" "$source_file"
}

status=0
for entry in 'waas-host:WaaSHost\\Updater' 'waas-payments:WaaSPayments\\Updater'; do
  package=${entry%%:*}
  namespace=${entry#*:}
  target="$root/packages/$package/src/Updater/Updater.php"
  if $check; then
    if ! render "$namespace" | cmp -s - "$target"; then
      echo "$target is out of date: run scripts/sync-updater.sh" >&2
      status=1
    fi
  else
    mkdir -p "$(dirname "$target")"
    render "$namespace" > "$target"
    echo "wrote $target"
  fi
done
exit $status
